defmodule Sample do
      # Concurrent clients share this set to claim each ID at most once.
      def start_link, do: Agent.start_link(fn -> MapSet.new() end)
      def claim(pid, id) do
        Agent.get_and_update(pid, fn seen ->
          {not MapSet.member?(seen, id), MapSet.put(seen, id)}
        end)
      end
    end

