defmodule Sample do
      def new, do: %{chunks: [], bytes: 0}
      def push(s, chunk), do: %{s | chunks: [chunk | s.chunks], bytes: s.bytes + byte_size(chunk)}
      def reset(s), do: %{s | chunks: []}
